def _load_frozen_module(_module_name, _payload_name):
    _payload = _FROZEN_PAYLOADS[_payload_name]
    _source = _payload.decode('utf-8')
    _module = _frozen_types.ModuleType(_module_name)
    _module.__file__ = f'<frozen:{_payload_name}>'
    _module.__package__ = ''
    _frozen_sys.modules[_module_name] = _module
    try:
        exec(
            compile(_source, _module.__file__, 'exec'),
            _module.__dict__,
        )
    except BaseException:
        _frozen_sys.modules.pop(_module_name, None)
        raise
    return _module


_load_frozen_module('base_policy', 'base_policy.py')
_load_frozen_module('counter_detection', 'counter_detection.py')
_load_frozen_module('counter_overlay', 'counter_overlay.py')
_frozen_entry = _load_frozen_module('_kaggriculture_frozen_entry', 'main.py')

agent = _frozen_entry.agent
if not callable(agent):
    raise TypeError('frozen entrypoint agent is not callable')

del _frozen_entry
del _load_frozen_module
del _frozen_base64
del _frozen_types
